#!/usr/bin/env node
// bootstrap: detect a repository's stack and generate the kit's project layer (usage and answers file: see DOC below).
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import * as K from './kitlib.js';
import * as G from './pr_gate.js';
import { ArgumentParser } from './args.js';

const HERE = K.realResolve(path.dirname(fileURLToPath(import.meta.url)));
export const KIT_DIR = path.dirname(HERE);
const VERSION_FILE = path.join(path.dirname(KIT_DIR), 'VERSION');
export const TODAY = K.isoSeconds().slice(0, 10); // local date, like datetime.date.today().isoformat()
export const KIT_OWNED = ['.claude/settings.json', '.claude/kit.json', '.claude/kit-manifest.json', 'scripts/sync.sh'];
export const HUMAN_OWNED = ['CLAUDE.md', 'ROADMAP.md', 'ARCHITECTURE.md', 'DESIGN.md', 'LESSONS.md'];
export const KIT_BLOCK_BEGIN = '<!-- kit:begin (regenerated by /bootstrap --upgrade; edit outside this block) -->'; // exact marker found in existing projects' CLAUDE.md: never change it
export const KIT_BLOCK_END = '<!-- kit:end -->';
/** Older kit defaults that an upgrade replaces with the current default (the human never chose them). */
export const KIT_DEFAULT_MIGRATIONS = {
  audit: { from: ['npm audit --audit-level=high'], to: 'node "$HOME/.claude/kit/scripts/ci_audit.js" --repo .' },
};
/** Commands the generated CI runs, with the job that runs them. Missing → the job fails; "none: <reason>" → skipped with a warning. */
/** A command that runs a script from the installed kit which this kit version does not have. */
export const staleKitCommand = (v) => {
  const m = typeof v === 'string' ? /\.claude\/kit\/scripts\/([\w.-]+)/.exec(v) : null;
  return m !== null && !K.isFile(path.join(KIT_DIR, 'scripts', m[1]));
};
export const CI_COMMANDS = ['test', 'coverage', 'format', 'integration', 'typecheck', 'lint', 'boundaries', 'audit', 'mutation'];

/**
 * Drop any wildcard rule another wildcard rule already covers, so the generated file carries each grant once and a
 * human reviewing it sees the real shape of what a lane may run. Only wildcard rules prune wildcard rules: whether
 * Claude Code's trailing `*` also matches the empty string is not documented, so an exact rule for a command with
 * no arguments after it is kept even when a wildcard rule looks like it covers the same command.
 */
export function pruneSubsumed(rules) {
  const parse = (r) => {
    const m = /^([A-Za-z_]+)\(([\s\S]*)\)$/.exec(r);
    return m && m[2].endsWith('*') ? { tool: m[1], pat: m[2] } : null;
  };
  return rules.filter((b) => {
    const mb = parse(b);
    if (!mb) return true;
    return !rules.some((a) => {
      if (a === b) return false;
      const ma = parse(a);
      return ma !== null && ma.tool === mb.tool && K.globMatch(mb.pat, [ma.pat]);
    });
  });
}

/**
 * permissions.allow rules for the commands this project records in kit.json, so the lane can run its own gates.
 * Derived, never listed: the project answered these at /zi-bootstrap and they are the only commands the kit tells a
 * lane to run. A `{file}` placeholder becomes the wildcard, since that is exactly the part that varies. The `*`
 * always lands after the program and subcommand, which is where Claude Code requires it
 * [docs: https://code.claude.com/docs/en/permissions.md @ 2026-11-13]; a compound command is matched per
 * subcommand, so `npx vitest run && rm -rf /` is not covered by the rule for `npx vitest run`.
 */
export function commandAllowRules(commands) {
  const rules = new Set();
  for (const v of Object.values(commands ?? {})) {
    if (typeof v !== 'string') continue;
    const cmd = v.trim();
    if (!cmd || /^none\b/i.test(cmd)) continue; // "none: <reason>" turns a check off on purpose
    const prefix = cmd.split('{')[0].trim();
    if (!prefix) continue;
    rules.add(`Bash(${prefix} *)`);
    if (prefix === cmd) rules.add(`Bash(${cmd})`); // the exact invocation, with no arguments after it
  }
  return [...rules];
}
/** gitleaks pinned by version and the sha256 of its linux_x64 release asset (from the release's checksums file). */
export const GITLEAKS = { version: '8.24.3', sha256: '9991e0b2903da4c8f6122b5c3186448b927a5da4deef1fe45271c3793f4ee29c' };
export const DEFAULT_KIT_REPO = 'jonathandrobles805/agents-system';
export const DEFAULT_BUDGETS = { research: { hours: 1, tool_calls: 200 }, plan: { hours: 1, tool_calls: 200 }, build: { hours: 4, tool_calls: 800 }, review: { hours: 1, tool_calls: 200 } };

const DOC = `bootstrap: detect a repository's stack and generate the kit's project layer.

Usage:
  bootstrap.js --repo PATH [--answers answers.json] [--dry-run] [--json] [--protect]
  bootstrap.js --repo PATH --detect-only --json        print detection and the questions, write nothing
  bootstrap.js --repo PATH --upgrade [--json]          refresh kit-owned files, back up what is replaced

Kit-owned files (regenerated on --upgrade): .claude/settings.json, .claude/kit.json (version, commands),
.claude/kit-manifest.json, scripts/sync.sh, the CI workflow. Human-owned files (written once, then only the
version stamp is touched): CLAUDE.md, ROADMAP.md, ARCHITECTURE.md, DESIGN.md, LESSONS.md, docs/.

Answers file (all optional; unanswered items become TODO(bootstrap) lines the human fills):
  {"project": "name", "wip_limit": 2, "milestones": [{"name": "...", "target": "..."}],
   "features": [{"name": "...", "slug": "...", "milestone": "M1"}],
   "layers": [{"name": "ui", "dirs": ["src/ui"], "imports": "application"}],
   "invariants": ["..."], "high_risk_paths": ["src/auth", "src/billing"],
   "commands": {"test": "...", "typecheck": "...", "lint": "..."}, "ci": "github"}`;

// ----------------------------------------------------------------------------- Python-compatibility helpers

const has = (o, k) => o !== null && typeof o === 'object' && Object.hasOwn(o, k);
const pyType = (v) => (v === null || v === undefined ? 'NoneType' : Array.isArray(v) ? 'list' : typeof v === 'string' ? 'str' : typeof v === 'boolean' ? 'bool' : typeof v === 'number' ? (Number.isInteger(v) ? 'int' : 'float') : 'dict');
/** dict.get(key, default); like Python it fails (AttributeError) when the value is not a dict. */
function get(o, k, dflt = null) {
  if (o === null || typeof o !== 'object' || Array.isArray(o)) throw new TypeError(`AttributeError: '${pyType(o)}' object has no attribute 'get'`);
  return Object.hasOwn(o, k) ? o[k] : dflt;
}
/** dict[key] (KeyError when missing) */
function req(o, k) {
  if (o === null || typeof o !== 'object') throw new TypeError(`'${typeof o}' object is not subscriptable`);
  if (!Object.hasOwn(o, k)) throw new Error(`KeyError: '${k}'`);
  return o[k];
}
/** list(x) for a JSON value: lists, the keys of a dict, the characters of a str; anything else is not iterable. */
function pyIter(v) {
  if (Array.isArray(v)) return v;
  if (v !== null && typeof v === 'object') return Object.keys(v);
  if (typeof v === 'string') return Array.from(v);
  throw new TypeError(`'${pyType(v)}' object is not iterable`);
}
/** Python truthiness */
const truthy = (v) => v !== null && v !== undefined && v !== false && v !== 0 && v !== '' && !(Array.isArray(v) && v.length === 0) && !(typeof v === 'object' && !Array.isArray(v) && Object.keys(v).length === 0);
/** Python code point ordering for sorted() on strings */
function cpCompare(a, b) {
  const x = Array.from(a);
  const y = Array.from(b);
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const p = x[i].codePointAt(0);
    const q = y[i].codePointAt(0);
    if (p !== q) return p < q ? -1 : 1;
  }
  return x.length - y.length < 0 ? -1 : x.length > y.length ? 1 : 0;
}

const STRICT_UTF8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
/**
 * Path.read_text(): UTF-8 with universal newlines ('\r\n' and '\r' become '\n'). Invalid UTF-8 raises (so a human-owned
 * file is never rewritten from a lossy copy); with `lossy` it is replaced instead, like read_text(errors="replace").
 */
function readText(p, lossy = false) {
  const buf = fs.readFileSync(p);
  const text = lossy ? buf.toString('utf8') : STRICT_UTF8.decode(buf);
  return text.replace(/\r\n?/g, '\n');
}

/** str.strip(): Python's whitespace set (differs from JS trim(): no U+FEFF, but U+001C..U+001F and U+0085). */
const PY_WS = '\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000';
const PY_STRIP = new RegExp(`^[${PY_WS}]+|[${PY_WS}]+$`, 'g');
const pyStrip = (s) => s.replace(PY_STRIP, '');

export const KIT_VERSION = K.isFile(VERSION_FILE) ? pyStrip(readText(VERSION_FILE)) : '0.0.0';

const NOT_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
function pyReprStr(s) {
  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = q;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === q || ch === '\\') out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp < 0x7f || (cp !== 0x20 && !NOT_PRINTABLE.test(ch))) out += ch;
    else if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out + q;
}
/** repr() of a JSON-shaped value (what an f-string shows for a list or dict). */
function pyRepr(v) {
  if (v === null || v === undefined) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'string') return pyReprStr(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  return '{' + Object.entries(v).map(([k, x]) => pyReprStr(k) + ': ' + pyRepr(x)).join(', ') + '}';
}
/** str() of a JSON-shaped value. */
const pyStr = (v) => (typeof v === 'string' ? v : pyRepr(v));

/** str(Path(p)): collapse repeated slashes, drop '.' components and a trailing slash. */
function pyPathStr(p) {
  const abs = p.startsWith('/');
  const parts = p.split('/').filter((x) => x !== '' && x !== '.');
  const lead = abs ? (p.startsWith('//') && !p.startsWith('///') ? '//' : '/') : '';
  return parts.length || abs ? lead + parts.join('/') : '.';
}
/** Path(p).name */
function pyName(p) {
  const parts = p.split('/').filter((x) => x !== '' && x !== '.');
  return parts.length ? parts[parts.length - 1] : '';
}

/** shutil.which */
function which(cmd) {
  let p = process.env.PATH;
  if (p === undefined) p = '/bin:/usr/bin';
  if (!p) return null;
  const ok = (fn) => {
    try {
      if (fs.statSync(fn).isDirectory()) return false;
      fs.accessSync(fn, fs.constants.X_OK);
      return true;
    } catch {
      return false;
    }
  };
  if (path.dirname(cmd) !== '.') return ok(cmd) ? cmd : null;
  const seen = new Set();
  for (const dir of p.split(':')) {
    if (seen.has(dir)) continue;
    seen.add(dir);
    const name = path.join(dir, cmd);
    if (ok(name)) return name;
  }
  return null;
}

/** os.scandir order (raw readdir order) as Dirent objects, or null when the directory cannot be read. */
function scandir(dir) {
  let d;
  try {
    d = fs.opendirSync(dir);
  } catch {
    return null;
  }
  const out = [];
  try {
    for (let e = d.readSync(); e; e = d.readSync()) out.push(e);
  } catch {
    // like os.scandir: stop at the first error
  } finally {
    try {
      d.closeSync();
    } catch {
      // ignore
    }
  }
  return out;
}

/** Path.is_file() for a scandir entry whose full path is `full` (follows symlinks). */
function entryIsFile(e, full) {
  if (e.isFile()) return true;
  if (e.isDirectory()) return false;
  try {
    return fs.statSync(full).isFile();
  } catch {
    return false;
  }
}
/** DirEntry.is_dir(follow_symlinks=False) */
function entryIsRealDir(e, full) {
  if (e.isDirectory()) return true;
  if (e.isSymbolicLink() || e.isFile()) return false;
  try {
    return fs.lstatSync(full).isDirectory();
  } catch {
    return false;
  }
}

/** Path.suffix */
function suffixOf(name) {
  const i = name.lastIndexOf('.');
  return i > 0 && i < name.length - 1 ? name.slice(i) : '';
}

/**
 * The first `limit` regular files of Path(d).rglob("*") (Python 3.13 traversal order), skipping anything below a
 * "node_modules" path component. Subtrees named node_modules are not entered (they contribute nothing).
 */
function rglobFiles(d, limit) {
  const files = [];
  if (d.split('/').includes('node_modules')) return files;
  const listing = (dir) => {
    const entries = scandir(dir);
    return entries ?? [];
  };
  const take = (dir, entries) => {
    for (const e of entries) {
      if (e.name === 'node_modules') continue;
      if (entryIsFile(e, path.join(dir, e.name))) {
        files.push(path.join(dir, e.name));
        if (files.length >= limit) return true;
      }
    }
    return false;
  };
  if (take(d, listing(d))) return files;
  const stack = [d];
  while (stack.length) {
    const cur = stack.pop();
    const entries = scandir(cur);
    if (entries === null) continue;
    for (const e of entries) {
      const full = path.join(cur, e.name);
      if (e.name !== 'node_modules' && entryIsRealDir(e, full)) {
        if (take(full, listing(full))) return files;
        stack.push(full);
      }
    }
  }
  return files;
}

/** Expand a Python re.sub replacement string (backslash escapes). The patterns used here have no groups. */
function pyRepl(repl) {
  if (!repl.includes('\\')) return () => repl;
  const esc = { a: '\x07', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t', v: '\v', '\\': '\\' };
  const isOct = (c) => c !== undefined && c >= '0' && c <= '7';
  const isDig = (c) => c !== undefined && c >= '0' && c <= '9';
  const parts = []; // strings, or null for "the whole match"
  let lit = '';
  for (let i = 0; i < repl.length; i++) {
    const ch = repl[i];
    if (ch !== '\\') {
      lit += ch;
      continue;
    }
    if (i + 1 >= repl.length) throw new Error('re.error: bad escape (end of pattern)');
    const c = repl[++i];
    if (c === 'g') {
      const m = /^g<([^>]*)>/.exec(repl.slice(i));
      if (!m || m[1] !== '0') throw new Error('re.error: invalid group reference');
      parts.push(lit, null);
      lit = '';
      i += m[0].length - 1;
    } else if (c === '0') {
      let n = '0';
      if (isOct(repl[i + 1])) {
        n += repl[++i];
        if (isOct(repl[i + 1])) n += repl[++i];
      }
      lit += String.fromCharCode(parseInt(n, 8) & 0xff);
    } else if (isDig(c)) {
      if (isOct(c) && isOct(repl[i + 1]) && isOct(repl[i + 2])) {
        const v = parseInt(c + repl[i + 1] + repl[i + 2], 8);
        if (v > 0o377) throw new Error('re.error: octal escape value outside of range 0-0o377');
        lit += String.fromCharCode(v);
        i += 2;
      } else {
        throw new Error('re.error: invalid group reference');
      }
    } else if (Object.hasOwn(esc, c)) {
      lit += esc[c];
    } else if (/[A-Za-z]/.test(c)) {
      throw new Error(`re.error: bad escape \\${c}`);
    } else {
      lit += '\\' + c;
    }
  }
  parts.push(lit);
  return (m) => parts.map((x) => (x === null ? m : x)).join('');
}
/** re.sub(pattern, repl, text) for a global JS regex and a Python-style replacement string. */
const reSub = (re, repl, text) => text.replace(re, pyRepl(repl));

// ----------------------------------------------------------------------------- detection

export function loadStacks() {
  const dir = path.join(KIT_DIR, 'stacks');
  return fs.readdirSync(dir)
    .filter((n) => n.endsWith('.json'))
    .sort(cpCompare)
    .map((n) => JSON.parse(readText(path.join(dir, n))));
}

/** json.loads: like JSON.parse, but the bare tokens NaN, Infinity and -Infinity are accepted (read here as null). */
export function pyJsonLoads(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    if (!/NaN|Infinity/.test(text)) throw e;
  }
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"') j += text[j] === '\\' ? 2 : 1;
      out += text.slice(i, j + 1);
      i = j;
    } else if (text.startsWith('-Infinity', i)) {
      out += 'null';
      i += 8;
    } else if (text.startsWith('Infinity', i)) {
      out += 'null';
      i += 7;
    } else if (text.startsWith('NaN', i)) {
      out += 'null';
      i += 2;
    } else {
      out += c;
    }
  }
  return JSON.parse(out);
}

export function readJson(p) {
  try {
    return pyJsonLoads(readText(p));
  } catch {
    return {};
  }
}

export function nodeDeps(root) {
  const pj = readJson(path.join(root, 'package.json'));
  const deps = new Set();
  for (const k of ['dependencies', 'devDependencies']) {
    const v = get(pj, k, {});
    if (truthy(v) && typeof v === 'object' && !Array.isArray(v)) for (const name of Object.keys(v)) deps.add(name);
  }
  return deps;
}

export function pythonDeps(root) {
  const names = new Set();
  const pp = path.join(root, 'pyproject.toml');
  if (K.isFile(pp)) {
    const txt = readText(pp, true);
    // quoted requirement specs anywhere: "fastapi>=0.110", "pytest", "ruff>=0.5; python_version>'3.8'"
    for (const m of txt.matchAll(/"([A-Za-z][A-Za-z0-9_.\-]*)(?:\[[^\]]*\])?\s*(?:[>=<~!;,@ ][^"]*)?"/g)) names.add(m[1].toLowerCase());
    // poetry-style tables: requests = "^2.0" / pytest = {version = "..."}
    for (const m of txt.matchAll(/^\s*([A-Za-z][A-Za-z0-9_.\-]*)\s*=\s*["{^]/gm)) names.add(m[1].toLowerCase());
    for (const tool of ['pytest', 'mypy', 'ruff', 'pyright', 'importlinter', 'mutmut']) {
      if (txt.includes(`[tool.${tool}`)) names.add(tool === 'importlinter' ? 'import-linter' : tool);
    }
  }
  const reqs = fs.readdirSync(root).filter((n) => K.fnmatch(n, 'requirements*.txt')).map((n) => path.join(root, n));
  reqs.push(path.join(root, 'Pipfile'));
  for (const req_ of reqs) {
    if (!K.isFile(req_)) continue;
    for (const line of K.splitlines(readText(req_, true))) {
      const m = /^\s*([A-Za-z0-9_.\-]+)/.exec(line);
      if (m && !pyStrip(line).startsWith('#')) names.add(m[1].toLowerCase());
    }
  }
  return names;
}

/** Which database a project uses and which lane adapter fits (KIT-SPEC 10.10). Evidence-based; `none` when nothing is found. */
export const DB_SIGNALS = [
  // [kind, adapter, how it shows up]
  ['supabase', 'emulator', (r, deps, files) => deps.has('@supabase/supabase-js') || files.has('supabase/config.toml')],
  ['firebase', 'emulator', (r, deps, files) => deps.has('firebase') || deps.has('firebase-admin') || files.has('firebase.json')],
  ['dynamodb', 'emulator', (r, deps) => deps.has('@aws-sdk/client-dynamodb') || deps.has('aws-sdk')],
  ['neon', 'branch', (r, deps) => deps.has('@neondatabase/serverless')],
  ['planetscale', 'branch', (r, deps) => deps.has('@planetscale/database')],
  ['postgres', 'local', (r, deps, files, text) => deps.has('pg') || deps.has('postgres') || deps.has('psycopg2') || deps.has('psycopg') || deps.has('asyncpg') || /provider\s*=\s*"postgresql"/.test(text) || /image:\s*postgres/.test(text)],
  ['mysql', 'local', (r, deps, files, text) => deps.has('mysql2') || deps.has('mysql') || deps.has('pymysql') || /provider\s*=\s*"mysql"/.test(text) || /image:\s*(mysql|mariadb)/.test(text)],
  ['mongodb', 'local', (r, deps, files, text) => deps.has('mongodb') || deps.has('mongoose') || deps.has('pymongo') || /provider\s*=\s*"mongodb"/.test(text) || /image:\s*mongo/.test(text)],
  ['sqlite', 'local', (r, deps, files, text) => deps.has('better-sqlite3') || deps.has('sqlite3') || /provider\s*=\s*"sqlite"/.test(text)],
];

export function detectDatabase(root) {
  const deps = new Set([...nodeDeps(root), ...pythonDeps(root)]);
  const files = new Set(['supabase/config.toml', 'firebase.json', 'prisma/schema.prisma', 'docker-compose.yml', 'docker-compose.yaml', 'compose.yml', 'compose.yaml'].filter((f) => K.isFile(path.join(root, f))));
  let text = '';
  for (const f of files) {
    if (f.endsWith('.prisma') || f.includes('compose')) text += readText(path.join(root, f), true) + '\n';
  }
  for (const [kind, adapter, test] of DB_SIGNALS) {
    if (test(root, deps, files, text)) return { kind, adapter, evidence: 'dependency or config file' };
  }
  return { kind: null, adapter: 'none', evidence: 'no database dependency or config found' };
}

/** The dependency-install command for a stack, from its lockfile: [command, evidence], or null when nothing says how. */
export function installCommand(root, stack) {
  const has = (f) => K.isFile(path.join(root, f));
  if (stack === 'node') {
    if (has('package-lock.json') || has('npm-shrinkwrap.json')) return ['npm ci', 'package-lock.json'];
    if (has('pnpm-lock.yaml')) return ['corepack enable && pnpm install --frozen-lockfile', 'pnpm-lock.yaml'];
    if (has('yarn.lock')) return has('.yarnrc.yml') ? ['corepack enable && yarn install --immutable', 'yarn.lock + .yarnrc.yml'] : ['yarn install --frozen-lockfile', 'yarn.lock'];
    if (has('bun.lockb') || has('bun.lock')) return ['npx --yes bun install --frozen-lockfile', 'bun lockfile'];
    return ['npm install', 'package.json without a lockfile'];
  }
  if (stack === 'python') {
    if (has('uv.lock')) return ['pip install uv && uv sync --frozen', 'uv.lock'];
    if (has('poetry.lock')) return ['pip install poetry && poetry install --no-interaction', 'poetry.lock'];
    if (has('requirements.txt')) return ['pip install -r requirements.txt', 'requirements.txt'];
    if (has('pyproject.toml')) return ['pip install -e .', 'pyproject.toml'];
    return null;
  }
  if (stack === 'go') return ['go mod download', 'go.mod'];
  if (stack === 'rust') return ['cargo fetch', 'Cargo.toml'];
  return null;
}

/** Top-level folders named by package.json workspaces ("apps/*" -> "apps"), existing only. */
export function workspaceDirs(root) {
  let pj;
  try {
    pj = JSON.parse(readText(path.join(root, 'package.json'), true));
  } catch {
    return [];
  }
  if (pj === null || typeof pj !== 'object') return [];
  const ws = Array.isArray(pj.workspaces) ? pj.workspaces : Array.isArray(pj.workspaces?.packages) ? pj.workspaces.packages : [];
  const out = [];
  for (const g of ws) {
    const top = String(g).replace(/^\.\//, '').split('/')[0];
    if (top && !top.includes('*') && K.isDir(path.join(root, top)) && !out.includes(top)) out.push(top);
  }
  return out;
}

/**
 * Drop or correct detected commands that point at things that do not exist (field test finding #8: a depcruise
 * command aimed at `src` and a config file the repo did not have). Every change is recorded with its reason.
 */
export function verifyDetected(root, result) {
  const c = result.commands;
  if (typeof c.boundaries === 'string' && c.boundaries.includes('depcruise')) {
    const cfg = ['.dependency-cruiser.cjs', '.dependency-cruiser.js', '.dependency-cruiser.json'].find((f) => K.isFile(path.join(root, f)));
    const targets = [...new Set([...['src', 'app', 'lib'].filter((d) => K.isDir(path.join(root, d))), ...workspaceDirs(root)])];
    if (!cfg) {
      delete c.boundaries;
      result.missing_tools.boundaries = 'dependency-cruiser is installed but has no config: write .dependency-cruiser.cjs (npx depcruise --init) from the real package dependencies';
      result.command_evidence.boundaries = 'dropped: no .dependency-cruiser.* config in the repo';
    } else if (!targets.length) {
      delete c.boundaries;
      result.missing_tools.boundaries = 'no source folder found for dependency-cruiser to scan; give the boundaries command by hand';
      result.command_evidence.boundaries = 'dropped: none of src/, app/, lib/ or the workspace folders exist';
    } else {
      c.boundaries = `npx depcruise --config ${cfg} ${targets.join(' ')}`;
      result.command_evidence.boundaries = `${cfg} exists; scans ${targets.join(', ')} (folders that exist)`;
    }
  }
  if (typeof c.typecheck === 'string' && c.typecheck.includes('tsc') && c.typecheck.includes('-p .') && !K.isFile(path.join(root, 'tsconfig.json'))) {
    delete c.typecheck;
    result.missing_tools.typecheck = 'typescript is installed but there is no root tsconfig.json; give the typecheck command by hand (for example tsc -b)';
    result.command_evidence.typecheck = 'dropped: no tsconfig.json at the repo root';
  }
}

export const isKitHookEntry = K.isKitHookEntry;

/**
 * The kit's hooks plus every hook the project already had (field test findings #1, #10): kit entries come first and
 * are always the current fragment; an older kit entry is replaced, never kept twice; the project's own entries are
 * kept in their order, on every bootstrap and every upgrade.
 */
export function mergeHooks(kitHooks, existingHooks) {
  const out = {};
  for (const [ev, entries] of Object.entries(kitHooks)) out[ev] = [...entries];
  if (existingHooks === null || typeof existingHooks !== 'object' || Array.isArray(existingHooks)) return out;
  for (const [ev, entries] of Object.entries(existingHooks)) {
    if (!Array.isArray(entries)) continue;
    const own = entries.filter((e) => !isKitHookEntry(e));
    if (own.length) out[ev] = [...(out[ev] ?? []), ...own];
  }
  return out;
}

const CI_INDENT = '          ';
/** A command is configured when it is a non-empty string that is not an explicit "none: <reason>". */
export const isConfigured = (v) => typeof v === 'string' && v.trim() !== '' && !/^none\b/i.test(v.trim());
const offReason = (v) => String(v).trim().replace(/^none\s*:?\s*/i, '') || 'no reason given';
const escapeEcho = (s) => String(s).replace(/["\\$`]/g, (m) => '\\' + m);

/**
 * The body of a CI `run: |` block for one command, indented for the template.
 * Configured → the command. "none: <reason>" → a visible warning, passes. Missing → an error, fails.
 * Paths into the installed kit ($HOME/.claude/kit/...) become $KIT_DIR/... (set by the kit's action in CI).
 */
export function ciRunBody(name, cmd, note = '') {
  if (isConfigured(cmd)) {
    return pyStr(cmd).replaceAll('$HOME/.claude/kit/', '$KIT_DIR/').split('\n').map((l) => CI_INDENT + l).join('\n');
  }
  if (typeof cmd === 'string' && cmd.trim() !== '') {
    return `${CI_INDENT}echo "::warning::${name} is off on purpose: ${escapeEcho(offReason(cmd))}"`;
  }
  return [
    `${CI_INDENT}echo "::error::${name} is not configured${escapeEcho(note)}. Set kit.json commands.${name} to a command, or to \\"none: <reason>\\" to turn it off on purpose."`,
    `${CI_INDENT}exit 1`,
  ].join('\n');
}

export function detect(root) {
  const stacks = loadStacks();
  const found = stacks.filter((s) => s.detect.some((f) => K.isFile(path.join(root, f))));
  const result = {
    stacks: [], frameworks: [], commands: {}, command_evidence: {}, missing_tools: {}, lockfiles: [], ci: null,
    dirs: [], existing_docs: [], tokens_file: null, branches: [], worktrees: [], credential_files: [],
    database: null, decisions_dir: null,
  };
  for (const s of found) {
    result.stacks.push(s.name);
    result.lockfiles.push(...s.lockfiles.filter((lf) => K.isFile(path.join(root, lf))));
    let present = new Set();
    if (s.name === 'node') {
      const deps = nodeDeps(root);
      present = new Set(deps);
      result.frameworks.push(...Object.entries(s.frameworks).filter(([k]) => deps.has(k)).map(([, v]) => v));
    } else if (s.name === 'python') {
      present = pythonDeps(root);
      result.frameworks.push(...Object.entries(s.frameworks).filter(([k]) => present.has(k)).map(([, v]) => v));
    } else if (s.name === 'go') {
      present = new Set(['go']);
      const gm = K.isFile(path.join(root, 'go.mod')) ? readText(path.join(root, 'go.mod'), true) : '';
      result.frameworks.push(...Object.entries(s.frameworks).filter(([k]) => gm.includes(k)).map(([, v]) => v));
      if (which('golangci-lint')) present.add('golangci-lint');
    } else if (s.name === 'rust') {
      present = new Set(['cargo']);
      const ct = K.isFile(path.join(root, 'Cargo.toml')) ? readText(path.join(root, 'Cargo.toml'), true) : '';
      result.frameworks.push(...Object.entries(s.frameworks).filter(([k]) => ct.includes(k)).map(([, v]) => v));
    }
    for (const [tool, cmds] of Object.entries(s.tools)) {
      if (present.has(tool)) {
        for (const [k, v] of Object.entries(cmds)) {
          if (!Object.hasOwn(result.commands, k)) {
            result.commands[k] = v;
            result.command_evidence[k] = `${tool} found in ${s.detect.find((f) => K.isFile(path.join(root, f)))}`;
          }
        }
      }
    }
    if (!Object.hasOwn(result.commands, 'audit')) {
      result.commands.audit = s.audit;
      result.command_evidence.audit = `kit default for the ${s.name} stack`;
    }
    if (!Object.hasOwn(result.commands, 'install')) {
      const inst = installCommand(root, s.name);
      if (inst) [result.commands.install, result.command_evidence.install] = inst;
    }
    for (const [want, hint] of Object.entries(s.install_hint ?? {})) {
      if (!Object.hasOwn(result.commands, want)) result.missing_tools[want] = hint;
    }
  }
  // KIT-SPEC 10.11 / OPERATING-MODEL §13 "forbidden to guess": a detected command that names a path or config
  // file that does not exist is not proposed; it becomes a missing tool with the reason.
  verifyDetected(root, result);
  // CI
  if (K.isDir(path.join(root, '.github'))) result.ci = 'github';
  else if (K.isFile(path.join(root, '.gitlab-ci.yml'))) result.ci = 'gitlab';
  // Folder map
  const skip = new Set(['node_modules', 'venv', '.venv', 'dist', 'build', 'target', '__pycache__']);
  const top = (scandir(root) ?? [])
    .map((e) => e.name)
    .filter((n) => !n.startsWith('.') && !skip.has(n) && K.isDir(path.join(root, n)))
    .sort(cpCompare);
  for (const name of top) {
    const files = rglobFiles(path.join(root, name), 2000);
    if (!files.length) continue;
    const ext = new Map();
    for (const f of files) {
      const sfx = suffixOf(path.basename(f));
      ext.set(sfx, (ext.get(sfx) ?? 0) + 1);
    }
    let best = '';
    let bestN = -1;
    for (const [sfx, n] of ext) {
      if (n > bestN) {
        best = sfx;
        bestN = n;
      }
    }
    result.dirs.push({ dir: name, files: files.length, main_ext: best });
  }
  // Existing docs and tokens
  for (const name of ['README.md', 'ARCHITECTURE.md', 'DESIGN.md', 'CONTRIBUTING.md', 'docs']) {
    if (fs.existsSync(path.join(root, name))) result.existing_docs.push(name);
  }
  // An existing decisions/ADR convention is adopted, never duplicated (KIT-SPEC 10.11)
  for (const cand of ['docs/decisions', 'docs/adr', 'adr', 'doc/adr', 'docs/architecture/decisions', 'docs/architecture-decisions']) {
    if (fs.existsSync(path.join(root, cand)) && fs.statSync(path.join(root, cand)).isDirectory()) {
      result.decisions_dir = cand;
      break;
    }
  }
  result.database = detectDatabase(root);
  for (const cand of ['tokens.css', 'src/tokens.css', 'src/styles/tokens.css', 'tailwind.config.js', 'tailwind.config.ts', 'src/theme.ts', 'theme.json', 'design-tokens.json']) {
    if (K.isFile(path.join(root, cand))) {
      result.tokens_file = cand;
      break;
    }
  }
  // Credential files that must never be readable by a lane
  for (const pat of ['.env', '.env.local', '.env.production', '*.pem', '*.key', 'service-account*.json', '.aws/credentials']) {
    if (pat.includes('*')) {
      for (const e of scandir(root) ?? []) {
        if (K.fnmatch(e.name, pat) && K.isFile(path.join(root, e.name))) result.credential_files.push(e.name);
      }
    } else if (K.isFile(path.join(root, pat))) {
      result.credential_files.push(pat);
    }
  }
  // Git state
  try {
    const parts = pyStrip(K.git(['symbolic-ref', '--short', 'refs/remotes/origin/HEAD'], root)).split('/');
    result.default_branch = parts[parts.length - 1];
  } catch {
    result.default_branch = 'main';
  }
  try {
    for (const line of K.splitlines(K.git(['for-each-ref', '--format=%(refname:short)', 'refs/heads'], root))) {
      const b = pyStrip(line);
      if (!b || b === result.default_branch) continue;
      let behind;
      let ahead;
      try {
        const nums = K.git(['rev-list', '--left-right', '--count', `${result.default_branch}...${b}`], root).split(/\s+/).filter(Boolean);
        if (nums.length !== 2) throw new Error('unpack');
        [behind, ahead] = nums;
      } catch {
        behind = '?';
        ahead = '?';
      }
      result.branches.push({ branch: b, behind, ahead });
    }
  } catch {
    // ignore
  }
  try {
    for (const line of K.git(['worktree', 'list', '--porcelain'], root).split('\n\n')) {
      const m = /^worktree (.+)$/m.exec(line);
      const b = /^branch (.+)$/m.exec(line);
      if (m) result.worktrees.push({ path: m[1], branch: b ? b[1].replaceAll('refs/heads/', '') : '(detached)' });
    }
  } catch {
    // ignore
  }
  return result;
}

export function questions(det, answers) {
  const q = [];
  const a = (k) => get(answers, k, null);
  if (!truthy(a('milestones')) || !truthy(a('features'))) {
    q.push({ id: 'roadmap', question: 'What are the milestones and the first features (name + slug) in order?', why: 'ROADMAP.md is the single source of truth; it is not guessed.' });
  }
  if (!has(answers, 'wip_limit')) q.push({ id: 'wip_limit', question: 'WIP limit (features in flight at once)?', default: 2 });
  if (!truthy(a('layers'))) {
    q.push({ id: 'layers', question: 'Architecture layers and allowed dependency direction?', draft: det.dirs.map((d) => d.dir), why: 'Becomes the import-boundary lint config.' });
  }
  if (!truthy(a('high_risk_paths'))) {
    q.push({ id: 'high_risk_paths', question: 'High-risk paths (auth, payments, migrations, public API, infra)?', default: K.DEFAULT_HIGH_RISK_PATHS });
  }
  if (!truthy(a('commands'))) {
    const have = det.commands;
    const unset = CI_COMMANDS.filter((n) => !(n === 'lint' ? (have.lint_all ?? have.lint) : have[n]));
    q.push({
      id: 'commands',
      question: 'Are these detected commands correct? Each shows where it was found. For every CI check listed under "not_configured", give a command or "none: <reason>" — a check with neither fails CI, a "none" check passes with a visible warning.',
      draft: det.commands, evidence: det.command_evidence, missing: det.missing_tools, not_configured: unset,
    });
  }
  if (!has(answers, 'db_adapter') && (!det.database || det.database.adapter === 'none')) {
    q.push({ id: 'db_adapter', question: 'No database was detected. Which lane database adapter applies: local, emulator, branch, or none (data layer mocked in lanes)?', default: 'none', why: 'Each lane gets a throwaway database of the project\'s kind; production credentials never enter a lane (KIT-SPEC 10.10).' });
  }
  if (det.credential_files.length) {
    q.push({ id: 'credentials', question: `Credential files found: ${pyRepr(det.credential_files)}. Lanes will be denied reading them. Confirm, or move them out of the repo.`, blocking: true });
  }
  if (det.branches.length) {
    const stale = det.branches.filter((b) => b.behind !== '0' && b.behind !== '?' && parseInt(b.behind, 10) > 20);
    if (stale.length) {
      q.push({ id: 'drift', question: `${stale.length} branch(es) are more than 20 commits behind ${det.default_branch}. Merge, sync, or delete them before bootstrapping lanes.`, branches: stale, blocking: false });
    }
  }
  return q;
}

// ----------------------------------------------------------------------------- generation

export const tmpl = (name) => readText(path.join(KIT_DIR, 'templates', name));

export function fill(text, values) {
  for (const [k, v] of values) text = text.replaceAll('{{' + k + '}}', () => pyStr(v));
  return text;
}

/** Replace any remaining {{placeholder}} with a TODO(bootstrap) marker the human can grep for. */
export function todo(text, label) {
  return text.replace(/\{\{([^}]*)\}\}/g, (m, g) => `TODO(bootstrap: ${label} — ${pyStrip(g)})`);
}

export const sha = (p) => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');

const regHome = () => (process.env.CLAUDE_HOME !== undefined ? process.env.CLAUDE_HOME : path.join(os.homedir(), '.claude'));

const ARCH_LAYERS = /\| \{\{ui\}\} \|.*\n\| \{\{application\}\} \|.*\n\| \{\{domain\}\} \|.*\n\| \{\{infrastructure\}\} \|.*/g;

export class Bootstrap {
  constructor(root, answers, dry, upgrade) {
    this.root = root;
    this.answers = answers;
    this.dry = dry;
    this.upgrade = upgrade;
    this.det = detect(root);
    this.written = [];
    this.skipped = [];
    this.backedUp = [];
    this.created = [];
    this.warnings = [];
    // The version being replaced, read before anything is written: run() rewrites .claude/kit.json early, so after
    // that the file names the new version. The backup directory is named for what it holds, not for what replaced it.
    const was = get(readJson(path.join(root, '.claude', 'kit.json')), 'kit_version', '');
    this.replaced = typeof was === 'string' && was ? was : 'unknown';
  }

  /** Where this upgrade's backup of the previous version lives. */
  backupDir() {
    return path.join(this.root, '.claude', 'backup', this.replaced);
  }

  /** Copy a file the upgrade is about to replace into the backup directory, timestamps kept (shutil.copy2). */
  backupFile(rel, p) {
    const bdir = this.backupDir();
    fs.mkdirSync(bdir, { recursive: true });
    const dst = path.join(bdir, rel.replaceAll('/', '__'));
    fs.copyFileSync(p, dst);
    const st = fs.statSync(p);
    fs.utimesSync(dst, st.atime, st.mtime);
    this.backedUp.push(rel);
  }

  write(rel, content, owned) {
    const p = path.join(this.root, rel);
    const existed = fs.existsSync(p);
    if (existed) {
      if (owned === 'human' && !this.upgrade) {
        // an existing CLAUDE.md keeps every byte; the kit's marked block is appended once (field test #13)
        if (rel === 'CLAUDE.md') {
          const old = readText(p);
          const nw = this.regenerateClaudeMd(old) ?? this.appendKitBlock(old);
          if (nw !== old) {
            if (!this.dry) fs.writeFileSync(p, nw);
            this.written.push('CLAUDE.md (kit block)');
            return;
          }
        }
        this.skipped.push(rel + ' (exists, human-owned)');
        return;
      }
      if (owned === 'human' && this.upgrade) {
        // refresh the kit version stamp line; in CLAUDE.md also regenerate the kit block, leaving the human's text untouched
        const old = readText(p);
        let nw = old.replace(/agent-kit \p{Nd}+\.\p{Nd}+\.\p{Nd}+/gu, () => `agent-kit ${KIT_VERSION}`);
        if (rel === 'CLAUDE.md') nw = this.regenerateClaudeMd(nw) ?? this.appendKitBlock(nw);
        if (nw !== old && !this.dry) {
          // backed up too: a restore must undo the stamp and the regenerated kit block, not only kit-owned files
          this.backupFile(rel, p);
          fs.writeFileSync(p, nw);
          this.written.push(rel + ' (version stamp)');
        } else {
          this.skipped.push(rel + ' (exists, human-owned)');
        }
        return;
      }
      if (owned === 'kit' && readText(p) === content) {
        this.skipped.push(rel + ' (unchanged)');
        return;
      }
      if (owned === 'kit' && this.upgrade && !this.dry) this.backupFile(rel, p);
    }
    if (!this.dry) {
      fs.mkdirSync(path.dirname(p), { recursive: true });
      fs.writeFileSync(p, content);
      if (rel.endsWith('.sh')) fs.chmodSync(p, 0o755);
      // a kit-owned file this upgrade introduced has nothing to restore from; a rollback removes it
      if (this.upgrade && owned === 'kit' && !existed) this.created.push(rel);
    }
    this.written.push(rel);
  }

  // -- individual files
  commands() {
    // Precedence: detected < already in kit.json (confirmed earlier) < answers given now. An upgrade without
    // --answers therefore keeps what the human confirmed (field test finding #21). A value equal to an older
    // kit default is the kit's, not the human's, and is replaced by the current default (KIT_DEFAULT_MIGRATIONS).
    const c = { ...this.det.commands };
    const existing = get(readJson(path.join(this.root, '.claude', 'kit.json')), 'commands', null);
    if (existing !== null && typeof existing === 'object' && !Array.isArray(existing)) {
      for (const [k, v] of Object.entries(existing)) {
        const old = KIT_DEFAULT_MIGRATIONS[k];
        if (old && old.from.includes(v)) c[k] = old.to;
        else if (staleKitCommand(v)) continue; // names a kit script this kit no longer has (e.g. a .py from the Python kit)
        else c[k] = v;
      }
    }
    const extra = get(this.answers, 'commands', {});
    if (extra !== null && typeof extra === 'object') Object.assign(c, extra);
    // No boundaries lint installed: use the kit's ARCHITECTURE.md-driven fallback so the gate exists from day one.
    if (!Object.hasOwn(c, 'boundaries')) c.boundaries = 'node "$HOME/.claude/kit/scripts/ci_boundaries_simple.js" --repo .';
    return c;
  }

  kitJson() {
    const existing = readJson(path.join(this.root, '.claude', 'kit.json'));
    const ans = this.answers;
    return {
      kit_version: KIT_VERSION,
      bootstrapped: get(existing, 'bootstrapped', TODAY),
      upgraded: this.upgrade ? TODAY : get(existing, 'upgraded', null),
      project: get(ans, 'project', get(existing, 'project', pyName(this.root))),
      stack: this.det.stacks,
      frameworks: this.det.frameworks,
      default_branch: get(this.det, 'default_branch', 'main'),
      ci: get(ans, 'ci', get(existing, 'ci', this.det.ci || 'github')),
      commands: this.commands(),
      wip_limit: get(ans, 'wip_limit', get(existing, 'wip_limit', 2)),
      high_risk_paths: get(ans, 'high_risk_paths', get(existing, 'high_risk_paths', K.DEFAULT_HIGH_RISK_PATHS)),
      secret_patterns: get(existing, 'secret_patterns', []),
      budgets: get(existing, 'budgets', DEFAULT_BUDGETS),
      mutation_threshold: get(existing, 'mutation_threshold', 70),
      mutation_blocking_after_features: get(existing, 'mutation_blocking_after_features', 2),
      mutation_in_ci: get(existing, 'mutation_in_ci', 'manual'),
      second_reviewer_model: get(existing, 'second_reviewer_model', get(ans, 'second_reviewer_model', '')), // empty = same model family, different checklist
      claude_md_cap_bytes: get(existing, 'claude_md_cap_bytes', 4000),
      // KIT-SPEC 10.10: the lane database adapter, from detection unless answered or already set
      db: get(existing, 'db', null) ?? { lane_adapter: get(ans, 'db_adapter', this.det.database?.adapter ?? 'none'), kind: this.det.database?.kind ?? null, evidence: this.det.database?.evidence ?? null },
      // KIT-SPEC 10.11: where the kit's artifacts live in this project; an existing convention is adopted
      paths: get(existing, 'paths', null) ?? { decisions: this.det.decisions_dir ?? 'docs/decisions', work: 'docs/specs' },
      sandbox: get(existing, 'sandbox', {}),
      lanes: get(existing, 'lanes', {}),
    };
  }

  settingsJson() {
    const frag = readJson(path.join(KIT_DIR, 'hooks', 'settings.project.json'));
    delete frag.$comment;
    const existing = readJson(path.join(this.root, '.claude', 'settings.json'));
    const merged = { ...existing };
    merged.hooks = mergeHooks(req(frag, 'hooks'), get(existing, 'hooks', null));
    const perms = get(existing, 'permissions', null);
    const permsObj = truthy(perms) ? perms : {};
    // the floor's deny list is the minimum (KIT-SPEC 10.9); the fragment and the project's own entries add to it
    // an inert path rule (Write/Glob/NotebookEdit/MultiEdit with a pattern) is dropped wherever it came from,
    // including a project's own file, so an upgrade clears the two the kit itself used to write
    const deny = new Set([...get(permsObj, 'deny', []), ...req(req(frag, 'permissions'), 'deny'), ...K.loadFloor().deny]
      .filter((d) => typeof d === 'string' && !K.inertPathRule(d)));
    for (const cf of this.det.credential_files) deny.add(`Read(${cf})`);
    const floor = K.loadFloor().deny;
    // deny unions with whatever the project already has, because more deny is always safe. allow is the opposite:
    // a grant left behind by an older kit is a grant nobody decided to keep, and an upgrade that only ever adds
    // could never take one back. So the kit owns the rules that name its own scripts and rewrites them each time;
    // every other allow rule belongs to the project and is preserved untouched.
    const fragAllow = get(req(frag, 'permissions'), 'allow', []);
    const ours = (a) => /\.claude[/\\]kit[/\\]/.test(a) && !fragAllow.includes(a);
    const allow = [...new Set([...get(permsObj, 'allow', []).filter((a) => typeof a === 'string' && !ours(a)), ...fragAllow, ...commandAllowRules(this.commands())])]
      // a rule that overlaps the floor is never written, so the generated file cannot disagree with ci_security_floor
      .filter((a) => typeof a === 'string' && a && !floor.some((d) => K.ruleOverlapsFloor(a, d)));
    const kept = pruneSubsumed(allow);
    merged.permissions = { ...permsObj, allow: kept.sort(cpCompare), deny: [...deny].sort(cpCompare) };
    return K.jsonDumps(merged, { indent: 2 }) + '\n';
  }

  /** The decisions folder this project already uses, or the kit's default. */
  decisionsDir() {
    return this.det.decisions_dir ?? 'docs/decisions';
  }

  /** Next number in the existing folder's own scheme (0001-, 001-, 1-); 0001 when the folder is empty or new. */
  nextDecisionNumber() {
    const dir = path.join(this.root, this.decisionsDir());
    let max = 0;
    let width = 4;
    for (const e of scandir(dir) ?? []) {
      const m = /^(\d+)[-_]/.exec(e.name);
      if (!m) continue;
      max = Math.max(max, parseInt(m[1], 10));
      width = m[1].length;
    }
    return String(max + 1).padStart(width, '0');
  }

  /** Path for a kit-written decision: the existing file with this slug when there is one (so a re-run never writes a second), else the next number. */
  decisionPath(slug) {
    const dir = this.decisionsDir();
    for (const e of scandir(path.join(this.root, dir)) ?? []) {
      if (new RegExp(`^\\d+[-_]${slug}\\.md$`).test(e.name)) return `${dir}/${e.name}`;
    }
    return `${dir}/${this.nextDecisionNumber()}-${slug}.md`;
  }

  claudeMd() {
    const cmds = this.commands();
    const dirs = this.det.dirs
      .map((d) => `- \`${d.dir}/\` — ${d.files} file${d.files !== 1 ? 's' : ''}, mostly \`${d.main_ext || 'mixed'}\``)
      .join('\n') || '- TODO(bootstrap: project map)';
    let text = fill(tmpl('claude-md.md'), [
      ['project', get(this.answers, 'project', pyName(this.root))], ['kit_version', KIT_VERSION], ['date', TODAY],
      ['test_cmd', get(cmds, 'test', 'TODO')], ['typecheck_cmd', get(cmds, 'typecheck', 'none')], ['lint_cmd', get(cmds, 'lint_all', get(cmds, 'lint', 'none'))],
    ]);
    text = text.replaceAll('- `{{dir}}/` — {{what lives here}}', () => dirs).replaceAll('- {{none}}', () => '- none yet');
    return todo(text, 'CLAUDE.md');
  }

  /** The part of CLAUDE.md the kit owns and regenerates on upgrade (KIT-SPEC 10.11); everything outside the markers is the human's. */
  claudeMdKitBlock() {
    const kit = this.kitJson();
    const lines = [
      KIT_BLOCK_BEGIN,
      `Kit: agent-kit ${KIT_VERSION} · sandbox: ${get(get(kit, 'sandbox', {}), 'runtime', 'auto (srt, else container, else degraded)')} · lane db: ${get(get(kit, 'db', {}), 'lane_adapter', 'none')}`,
      '',
      'Read first, every lane: `ROADMAP.md`, `ARCHITECTURE.md`, `DESIGN.md`, `LESSONS.md`, `docs/context/` if present, and the spec the lane names.',
      `Decisions: \`${get(get(kit, 'paths', {}), 'decisions', 'docs/decisions')}/\`. Lane artifacts: \`${get(get(kit, 'paths', {}), 'work', 'docs/specs')}/\`.`,
      'Hooks block: edits of unread or out-of-spec files, secret reads (kit/security/floor.json), destructive commands, force pushes, edits to `.claude/`.',
      'A lane never holds production credentials; the sandbox makes their paths unreadable.',
      KIT_BLOCK_END,
    ];
    return lines.join('\n') + '\n';
  }

  /** Append the kit block to a CLAUDE.md that has none, after one blank line; the human's text is not touched. */
  appendKitBlock(old) {
    if (old.includes(KIT_BLOCK_BEGIN)) return old;
    const sep = old === '' ? '' : old.endsWith('\n\n') ? '' : old.endsWith('\n') ? '\n' : '\n\n';
    return old + sep + this.claudeMdKitBlock();
  }

  /** On upgrade: replace the kit block in an existing CLAUDE.md, leave the rest byte-for-byte. Returns null when there is no block to replace. */
  regenerateClaudeMd(old) {
    const b = old.indexOf(KIT_BLOCK_BEGIN);
    const e = old.indexOf(KIT_BLOCK_END);
    if (b < 0 || e < 0 || e < b) return null;
    return old.slice(0, b) + this.claudeMdKitBlock().trimEnd() + old.slice(e + KIT_BLOCK_END.length);
  }

  roadmap() {
    const ms = get(this.answers, 'milestones', null);
    const fs_ = get(this.answers, 'features', null);
    const msList = truthy(ms) ? ms : [];
    const fsList = truthy(fs_) ? fs_ : [];
    // No WIP number is filled in. ROADMAP.md is human-owned, so an upgrade only refreshes its version stamp and a
    // number written here would be frozen at bootstrap while kit.json's moved on -- which is how a real run ended
    // up with 1 in the roadmap and 2 in kit.json, and the planner reading the stale one.
    let text = fill(tmpl('roadmap.md'), [['version', KIT_VERSION], ['date', TODAY]]);
    if (msList.length) {
      const rows = msList.map((m, i) => `| M${i + 1} | ${pyStr(req(m, 'name'))} | ${pyStr(get(m, 'target', '—'))} | ${pyStr(get(m, 'status', 'planned'))} |`).join('\n');
      text = reSub(/\| M1 \| \{\{milestone\}\} \|.*\|/g, rows, text);
    }
    if (fsList.length) {
      const rows = fsList.map((f) => `| ${pyStr(req(f, 'name'))} | ${pyStr(req(f, 'slug'))} | ${pyStr(get(f, 'milestone', 'M1'))} | queued | — | — | — |`).join('\n');
      text = reSub(/\| \{\{feature\}\} \| \{\{slug\}\} \|.*\|/g, rows, text);
      const queue = fsList.map((f, i) => `${i + 1}. ${pyStr(req(f, 'slug'))}`).join('\n');
      text = text.replaceAll('1. {{slug}}', () => queue);
    }
    return todo(text, 'ROADMAP.md');
  }

  architecture() {
    let text = tmpl('architecture.md').replaceAll('{{date}}', () => TODAY);
    const layers = get(this.answers, 'layers', null);
    if (truthy(layers)) {
      const rows = layers.map((l) => `| ${pyStr(req(l, 'name'))} | \`${get(l, 'dirs', []).map(pyStr).join('`, `')}\` | ${pyStr(get(l, 'imports', 'nothing in the app'))} |`).join('\n');
      text = reSub(ARCH_LAYERS, rows, text);
    } else {
      const draft = this.det.dirs.map((d) => `| TODO(bootstrap: layer name) | \`${d.dir}\` | TODO(bootstrap: may import from) |`).join('\n') || '| TODO(bootstrap: layer) | TODO | TODO |';
      text = reSub(ARCH_LAYERS, draft, text);
    }
    const invRaw = get(this.answers, 'invariants', null);
    const inv = truthy(invRaw) ? invRaw : [];
    if (inv.length) {
      const items = inv.map((i) => `- [ ] ${pyStr(i)}`).join('\n');
      text = text.replaceAll('- [ ] {{invariant, stated so it can be checked}}', () => items);
    }
    const hrRaw = get(this.answers, 'high_risk_paths', null);
    const hr = truthy(hrRaw) ? hrRaw : K.DEFAULT_HIGH_RISK_PATHS;
    const hrText = hr.map((p) => `- \`${pyStr(p)}\``).join('\n');
    text = text.replaceAll('- `{{path}}`', () => hrText);
    return todo(text, 'ARCHITECTURE.md');
  }

  design() {
    const tokens = this.det.tokens_file || 'TODO(bootstrap: tokens file path)';
    const text = tmpl('design.md').replaceAll('{{date}}', () => TODAY).replaceAll('{{path}}', () => tokens);
    return todo(text, 'DESIGN.md');
  }

  lessons() {
    return '# Lessons\n\nRules the system learned. The Debt section lists rules not yet enforced by a check; keep it short.\n\n## Debt\n\n- none\n';
  }

  syncSh() {
    const cmds = this.commands();
    const branch = get(this.det, 'default_branch', 'main');
    return `#!/usr/bin/env bash
# sync: bring this worktree up to date with ${branch} and prove it still passes. Generated by agent-kit ${KIT_VERSION}.
set -euo pipefail
BASE="\${1:-${branch}}"
if git remote get-url origin >/dev/null 2>&1; then
  git fetch origin "$BASE"
  TARGET="origin/$BASE"
else
  TARGET="$BASE"
fi
# --no-ff: the lane keeps its own first-parent line, so a lane with nothing of its own never looks merged
if ! git merge --no-ff --no-edit "$TARGET"; then
  echo "sync: merge conflict with $BASE. Resolve once (counts as a failed attempt), re-run tests, or escalate." >&2
  exit 3
fi
${this.syncInstall(cmds)}${isConfigured(get(cmds, 'test', null)) ? pyStr(get(cmds, 'test', '')) : 'echo "sync: no test command configured; nothing proves this worktree passes" >&2; exit 4'}
echo "sync: up to date with $BASE and tests pass"
`;
  }

  /** sync.sh: install dependencies when this worktree has never installed them or a lockfile changed (field test #34). */
  syncInstall(cmds) {
    const inst = get(cmds, 'install', null);
    if (!isConfigured(inst)) return '';
    return `# dependencies: install when this worktree never did, or when a lockfile changed since the last install
LOCKSUM="$({ cat package-lock.json npm-shrinkwrap.json pnpm-lock.yaml yarn.lock bun.lock uv.lock poetry.lock requirements.txt go.sum Cargo.lock 2>/dev/null || true; } | sha256sum | cut -c1-16)"
MARK=.claude/session/install.sum
if [ ! -f "$MARK" ] || [ "$(cat "$MARK")" != "$LOCKSUM" ]; then
  echo "sync: installing dependencies (${pyStr(inst).replaceAll('"', '\\"')})"
  ${pyStr(inst)}
  mkdir -p .claude/session && echo "$LOCKSUM" > "$MARK"
fi
`;
  }

  ciWorkflow() {
    const cmds = this.commands();
    const kit = this.kitJson();
    const tpl = readText(path.join(KIT_DIR, 'ci', 'github.yml'));
    const lane = get(get(kit, 'db', {}), 'lane_adapter', 'none');
    const resolve = (name) => {
      if (name === 'lint') {
        const all = get(cmds, 'lint_all', null);
        if (all !== null) return all;
        const one = get(cmds, 'lint', null);
        return one === null ? null : pyStr(one).replaceAll('{file}', '.');
      }
      return get(cmds, name, null);
    };
    const values = [];
    for (const name of CI_COMMANDS) {
      let body = ciRunBody(name, resolve(name), name === 'integration' ? ` (kit.json db.lane_adapter: ${lane})` : '');
      // the coverage floor is part of the coverage step; a coverage step turned off or missing has no floor to check
      if (name === 'coverage' && isConfigured(resolve('coverage'))) body += `\n${CI_INDENT}node "$KIT_DIR/scripts/ci_coverage_floor.js" --repo . --base origin/${kit.default_branch}`;
      values.push([name, body]);
    }
    const [repo, ref] = this.kitRef();
    const text = fill(tpl, [
      ...values, ['setup', this.ciSetup(cmds)], ['default_branch', kit.default_branch],
      ['kit_version', KIT_VERSION], ['kit_repo', repo], ['kit_ref', ref],
      ['gitleaks_version', GITLEAKS.version], ['gitleaks_sha256', GITLEAKS.sha256],
      ['mutation_if', get(kit, 'mutation_in_ci', 'manual') === 'pr' ? 'true' : "github.event_name == 'workflow_dispatch'"],
      ['mutation_threshold', pyStr(kit.mutation_threshold)], ['mutation_blocking_after', pyStr(kit.mutation_blocking_after_features)],
    ]);
    return ['.github/workflows/kit.yml', text];
  }

  /**
   * Where CI gets the kit: [owner/repo, ref]. The ref is the installed kit's commit when that commit is on its remote
   * (exactly the scripts this project was bootstrapped with), else the version tag; either way a warning says so.
   */
  kitRef() {
    const kit = readJson(path.join(this.root, '.claude', 'kit.json'));
    let repo = get(kit, 'kit_repo', null);
    const g = (args) => spawnSync('git', ['-C', KIT_DIR, ...args], { encoding: 'utf8', timeout: 20000 });
    if (!repo) {
      const m = /github\.com[:/]([^/\s]+\/[^/\s]+?)(?:\.git)?\s*$/.exec(g(['config', '--get', 'remote.origin.url']).stdout ?? '');
      repo = m ? m[1] : DEFAULT_KIT_REPO;
    }
    const head = (g(['rev-parse', 'HEAD']).stdout ?? '').trim();
    const pushed = /^[0-9a-f]{40}$/.test(head) && (g(['branch', '-r', '--contains', head]).stdout ?? '').trim() !== '';
    const dirty = (g(['status', '--porcelain', '--', '.']).stdout ?? '').trim() !== '';
    if (dirty) this.warnings.push(`the installed kit (${KIT_DIR}) has uncommitted changes; CI runs the committed kit, and guards-present will report the difference`);
    if (pushed) return [repo, head];
    this.warnings.push(`the installed kit's commit is not on its remote; CI pins ${repo}@v${KIT_VERSION} instead. Push the kit, then run /zi-bootstrap --upgrade to pin the exact commit`);
    return [repo, `v${KIT_VERSION}`];
  }

  /** Runtime and dependency install steps for every detected stack; the install command comes from kit.json commands.install. */
  ciSetup(cmds) {
    const has = (f) => K.isFile(path.join(this.root, f));
    const lines = [];
    const stacks = this.det.stacks;
    // Node is set up whatever the project's stack is, because the KIT is Node: commands.boundaries defaults to a
    // kit script and audit usually is one, so these jobs run node even in a Python-only repository. Detection used
    // to gate this, which left a repository whose package.json does not exist yet -- the state every project is in
    // before its first code lands -- running kit scripts on whatever node the runner happens to ship, while the
    // kit's own jobs pinned 22 two screens further down the same file. A pin the project made is still the pin.
    const ver = has('.nvmrc') ? 'node-version-file: ".nvmrc"' : has('.node-version') ? 'node-version-file: ".node-version"' : 'node-version: "22"';
    lines.push('      - uses: actions/setup-node@v4', `        with: { ${ver} }`);
    if (stacks.includes('python')) {
      const ver = has('.python-version') ? 'python-version-file: ".python-version"' : 'python-version: "3.12"';
      lines.push('      - uses: actions/setup-python@v5', `        with: { ${ver} }`);
    }
    if (stacks.includes('go')) lines.push('      - uses: actions/setup-go@v5', '        with: { go-version-file: "go.mod" }');
    const inst = get(cmds, 'install', null);
    if (isConfigured(inst)) lines.push('      - name: install dependencies', '        run: |', ...pyStr(inst).split('\n').map((l) => CI_INDENT + l));
    else if (inst !== null) lines.push('      - name: install dependencies (off on purpose)', `        run: echo "::warning::install is off on purpose: ${escapeEcho(offReason(inst))}"`);
    return lines.join('\n');
  }

  /** .github/CODEOWNERS: CI and kit configuration need the owner's review (KIT-SPEC 7.4). Human-owned: written once, never overwritten. */
  codeowners() {
    let owner = get(this.answers, 'owner', null);
    if (!owner) {
      try {
        const m = /github\.com[:/]([^/]+)\//.exec(pyStrip(K.git(['config', '--get', 'remote.origin.url'], this.root)));
        if (m) owner = m[1];
      } catch {
        owner = null;
      }
    }
    const who = owner ? `@${owner}` : 'TODO(bootstrap: CODEOWNERS — GitHub user or team)';
    return `# Generated by agent-kit ${KIT_VERSION}. Changes to CI and kit configuration need a code owner's review (KIT-SPEC 7.4).\n` +
      `# Branch protection set by /zi-bootstrap --protect requires code-owner review for these paths.\n` +
      `/.github/workflows/ ${who}\n/.github/CODEOWNERS ${who}\n/.claude/ ${who}\n/CLAUDE.md ${who}\n/ARCHITECTURE.md ${who}\n`;
  }

  gitignore() {
    const p = path.join(this.root, '.gitignore');
    const wanted = ['.claude/session/', '.claude/lane.json', '.claude/backup/', '.claude/settings.local.json'];
    const existing = K.isFile(p) ? K.splitlines(readText(p)) : [];
    const add = wanted.filter((w) => !existing.includes(w));
    if (add.length && !this.dry) fs.writeFileSync(p, [...existing, '', '# agent-kit', ...add].join('\n') + '\n');
    if (add.length) this.written.push(`.gitignore (+${add.length})`);
  }

  /** Add this repo to ~/.claude/kit-projects.json so /zi-status --all and the dashboard find it. */
  registerProject() {
    const reg = path.join(regHome(), 'kit-projects.json');
    let items;
    try {
      items = K.isFile(reg) ? pyJsonLoads(readText(reg)) : [];
    } catch (e) {
      if (!(e instanceof SyntaxError)) throw e;
      items = [];
    }
    const me = pyPathStr(this.root);
    // `str(root) not in items`, then items.append(...): a dict or a string "contains" things too, only a list can be appended to
    let contained;
    if (Array.isArray(items)) contained = items.includes(me);
    else if (items !== null && typeof items === 'object') contained = Object.hasOwn(items, me);
    else if (typeof items === 'string') contained = items.includes(me);
    else throw new TypeError(`argument of type '${pyType(items)}' is not iterable`);
    if (!contained) {
      if (!Array.isArray(items)) throw new TypeError(`AttributeError: '${pyType(items)}' object has no attribute 'append'`);
      items.push(me);
      fs.mkdirSync(path.dirname(reg), { recursive: true });
      fs.writeFileSync(reg, K.jsonDumps(items, { indent: 2 }) + '\n');
    }
  }

  manifest() {
    const files = {};
    for (const rel of [...KIT_OWNED, '.github/workflows/kit.yml']) {
      const p = path.join(this.root, rel);
      if (K.isFile(p) && rel !== '.claude/kit-manifest.json') files[rel] = sha(p);
    }
    // the kit's own scripts (JavaScript since the port): guards-present compares these hashes against ~/.claude/kit
    const scriptsDir = path.join(KIT_DIR, 'scripts');
    const scripts = {};
    for (const n of fs.readdirSync(scriptsDir).filter((x) => x.endsWith('.js')).sort(cpCompare)) scripts[n] = sha(path.join(scriptsDir, n));
    return K.jsonDumps({ kit_version: KIT_VERSION, generated: TODAY, files, kit_scripts: scripts }, { indent: 2 }) + '\n';
  }

  run() {
    if (!this.upgrade) {
      this.write('CLAUDE.md', this.claudeMd() + '\n' + this.claudeMdKitBlock(), 'human');
      this.write('ROADMAP.md', this.roadmap(), 'human');
      this.write('ARCHITECTURE.md', this.architecture(), 'human');
      this.write('DESIGN.md', this.design(), 'human');
      this.write('LESSONS.md', this.lessons(), 'human');
      this.write('.github/CODEOWNERS', this.codeowners(), 'human');
      this.write('docs/research/INDEX.md', tmpl('index.md'), 'human');
      const work = get(get(this.kitJson(), 'paths', {}), 'work', 'docs/specs');
      this.write(`${work}/README.md`, '# Specs\n\nOne file per feature, from `~/.claude/kit/templates/spec.md`. Companion files: `<slug>.progress.md`, `<slug>.review.md`, `<slug>.events.jsonl`; check output goes to `.claude/session/<slug>.log`.\n', 'human');
      this.write(this.decisionPath('adopt-agent-kit'), fill(tmpl('decision.md'), [
        ['NNNN', this.nextDecisionNumber()], ['title', 'Adopt the agent kit'], ['date', TODAY],
        ['what situation forced a decision', 'Agents guessed, branches drifted, and rules lived only in prompts.'],
        ['what was decided', `Adopt agent-kit ${KIT_VERSION}: specs with provenance tags, hooks that block unread or out-of-spec edits, a fresh-context reviewer, one worktree per feature, retro after every merge.`],
        ['alternative', 'Longer prompts and manual review'], ['why not', 'Prompts are skimmed; manual review does not scale past one lane.'],
        ['what this makes easier, what it makes harder', 'Easier: parallel features with gates. Harder: every rule must be expressible as a check.'],
      ]), 'human');
    } else {
      for (const rel of HUMAN_OWNED) {
        if (K.isFile(path.join(this.root, rel))) this.write(rel, '', 'human');
      }
    }
    this.write('.claude/kit.json', K.jsonDumps(this.kitJson(), { indent: 2 }) + '\n', 'kit');
    this.write('.claude/settings.json', this.settingsJson(), 'kit');
    this.write('scripts/sync.sh', this.syncSh(), 'kit');
    const [rel, text] = this.ciWorkflow();
    this.write(rel, text, 'kit');
    this.gitignore();
    if (!this.dry) {
      this.write('.claude/kit-manifest.json', this.manifest(), 'kit');
      this.registerProject();
    }
    return {
      kit_version: KIT_VERSION, written: this.written, skipped: this.skipped, backed_up: this.backedUp,
      warnings: [...new Set(this.warnings)], detection: this.det, questions: questions(this.det, this.answers), dry_run: this.dry,
    };
  }
}

// ----------------------------------------------------------------------------- upgrade as a transaction (KIT-SPEC 11)

/**
 * The checks an upgrade can evaluate against a project's own files. Both are read-only and take a repository, which
 * is what makes them usable here; the planted-fault suite is not (it builds and destroys its own fixtures and takes
 * no --repo), so it stays the kit's release gate.
 */
export const PROJECT_CHECKS = [
  ['guards-present', 'ci_guards_present.js', (root) => ['--repo', root, '--kit', KIT_DIR]],
  ['security-floor', 'ci_security_floor.js', (root) => ['--repo', root]],
];

/** Run every project check as its own process (they write to stdout/stderr and must not land in this script's output). */
export function projectChecks(root) {
  return PROJECT_CHECKS.map(([name, script, argsOf]) => {
    const r = spawnSync(process.execPath, [path.join(KIT_DIR, 'scripts', script), ...argsOf(root)], {
      encoding: 'utf8', timeout: 120000, maxBuffer: 1 << 26,
    });
    const text = pyStrip(`${r.stdout ?? ''}${r.stderr ?? ''}`);
    return { name, ok: r.status === 0, output: Array.from(text).slice(0, 400).join('') };
  });
}

/**
 * Put the project back as it was: every replaced file from the backup, and away with every file the upgrade created.
 * The shape of lane.js undo(), which removes the worktree and branch when start refuses after creating them.
 * `.gitignore` is not covered: gitignore() only ever appends the kit's own ignore lines, which are inert after a
 * rollback, and rewriting a human's ignore file to undo an append would risk more than it repairs.
 */
export function restoreBackup(root, dir, replaced, created) {
  const done = [];
  for (const rel of replaced) {
    const src = path.join(dir, rel.replaceAll('/', '__'));
    if (!K.isFile(src)) continue;
    const dst = path.join(root, rel);
    fs.mkdirSync(path.dirname(dst), { recursive: true });
    fs.copyFileSync(src, dst);
    done.push(rel);
  }
  for (const rel of created) {
    fs.rmSync(path.join(root, rel), { force: true });
    done.push(`${rel} (removed)`);
  }
  return done;
}

/**
 * The checks that passed in the baseline and fail now. A check red both before and after is not a regression: a
 * project behind the current kit fails guards-present by design, and bringing it up to date is the reason to
 * upgrade, so a pre-check that had to be green would make every version bump unupgradeable.
 */
export function regressions(before, after) {
  return after.filter((a) => !a.ok && before.some((x) => x.name === a.name && x.ok));
}

/** `--upgrade`: baseline the project checks, apply, check again, restore on a regression. */
export function upgradeProject(root, answers, dry) {
  const b = new Bootstrap(root, answers, dry, true);
  if (dry) return b.run(); // nothing is written, so there is nothing to verify or undo
  const before = projectChecks(root);
  const result = b.run();
  const after = projectChecks(root);
  const regressed = regressions(before, after);
  result.checks = { before, after, regressed: regressed.map((c) => c.name), restored: null };
  if (regressed.length) {
    result.checks.restored = restoreBackup(root, b.backupDir(), result.backed_up, b.created);
    result.checks.after_restore = projectChecks(root);
    result.checks.backup = path.join('.claude', 'backup', b.replaced);
  }
  return result;
}

/** Python's str(exception) for a failed subprocess, as protect_branch put it into its result. */
function failText(e, args, timeout) {
  if (e && e.code === 'ETIMEDOUT') return `Command '${pyRepr(args)}' timed out after ${timeout} seconds`;
  if (e && e.code === 'ENOENT') return `[Errno 2] No such file or directory: '${args[0]}'`;
  if (e && e.code === 'EACCES') return `[Errno 13] Permission denied: '${args[0]}'`;
  if (e && typeof e.status === 'number') return `Command '${pyRepr(args)}' returned non-zero exit status ${e.status}.`;
  return String(e && e.message !== undefined ? e.message : e);
}

/** Set branch protection through gh. Returns a result dict; never throws. */
export function protectBranch(root, branch, checks) {
  if (!which('gh')) return { ok: false, reason: 'gh not installed' };
  try {
    let remote;
    const cfg = ['git', 'config', '--get', 'remote.origin.url'];
    try {
      remote = pyStrip(K.git(cfg.slice(1), root));
    } catch (e) {
      throw Object.assign(new Error(failText(e, cfg)), { pyText: true });
    }
    const m = /github\.com[:/]([^/]+)\/([^/.]+)/.exec(remote);
    if (!m) return { ok: false, reason: `origin is not GitHub: ${remote}` };
    const [owner, repo] = [m[1], m[2]];
    // KIT-SPEC 7.4: required checks, no force pushes, and a code owner's review for the paths CODEOWNERS names
    // (required_approving_review_count 0 keeps ordinary PRs review-free; only CODEOWNERS paths need an owner).
    const body = {
      required_status_checks: { strict: true, contexts: checks }, enforce_admins: false,
      required_pull_request_reviews: { require_code_owner_reviews: true, required_approving_review_count: 0, dismiss_stale_reviews: true },
      restrictions: null, allow_force_pushes: false, allow_deletions: false,
    };
    const args = ['gh', 'api', '-X', 'PUT', `repos/${owner}/${repo}/branches/${branch}/protection`, '--input', '-'];
    const r = spawnSync(args[0], args.slice(1), { input: K.jsonDumps(body), encoding: 'utf8', timeout: 60000 });
    if (r.error) throw Object.assign(new Error(failText(r.error, args, 60)), { pyText: true });
    const rc = r.status ?? -1;
    const out = { ok: rc === 0, reason: rc !== 0 ? Array.from(pyStrip(r.stderr ?? '')).slice(0, 300).join('') : '', repo: `${owner}/${repo}` };
    // Merge queue, best effort: a repository ruleset with a merge_queue rule (the branch-protection API cannot set it).
    if (rc === 0) {
      const ruleset = { name: 'kit merge queue', target: 'branch', enforcement: 'active', conditions: { ref_name: { include: [`refs/heads/${branch}`], exclude: [] } }, rules: [{ type: 'merge_queue', parameters: { check_response_timeout_minutes: 60, grouping_strategy: 'ALLGREEN', max_entries_to_build: 5, max_entries_to_merge: 5, merge_method: 'SQUASH', min_entries_to_merge: 1, min_entries_to_merge_wait_minutes: 5 } }] };
      const q = spawnSync('gh', ['api', '-X', 'POST', `repos/${owner}/${repo}/rulesets`, '--input', '-'], { input: K.jsonDumps(ruleset), encoding: 'utf8', timeout: 60000 });
      out.merge_queue = q.status === 0 ? 'enabled' : `not enabled: ${Array.from(pyStrip(q.stderr ?? '')).slice(0, 200).join('')} (merge queues need a GitHub plan that supports rulesets on this repository)`;
    }
    return out;
  } catch (e) {
    return { ok: false, reason: e && e.pyText ? e.message : failText(e, [], 0) };
  }
}

// ----------------------------------------------------------------------------- command line

const PY_USAGE = 'usage: bootstrap.js [-h] [--repo REPO] [--answers ANSWERS] [--dry-run]\n                    [--detect-only] [--upgrade] [--all] [--protect] [--json]';
const HELP_HEAD = DOC;
const HELP_OPTIONS = `options:
  -h, --help         show this help message and exit
  --repo REPO
  --answers ANSWERS
  --dry-run
  --detect-only
  --upgrade
  --all              with --upgrade: every project in ~/.claude/kit-
                     projects.json
  --protect          set GitHub branch protection via gh
  --json
`;

/**
 * args.js has no prefix abbreviations, no "ignored explicit argument" errors, a different usage line and keeps unknown
 * options and stray words in a different order than argparse, so this parser replays argparse's two passes itself
 * (classify every token, then consume left to right) on top of the options declared with addArgument.
 */
class BootstrapParser extends ArgumentParser {
  usage() {
    return PY_USAGE;
  }

  parseArgs(argv) {
    const specs = [{ flags: ['-h', '--help'], kind: 'help' }, ...this.options.map((o) => ({ flags: o.flags, kind: o.action === 'store' ? 'store' : 'flag', dest: o.dest, default: o.default }))];
    const table = specs.flatMap((sp) => sp.flags.map((f) => [f, sp]));
    const exact = (f) => table.find(([k]) => k === f)?.[1];
    const label = (sp) => sp.flags.join('/');
    // pass 1 (argparse's _parse_optional on every token before the first '--'; ambiguity is reported here)
    const classify = (tok) => {
      if (tok === '' || tok[0] !== '-') return { pos: true };
      const ex = exact(tok);
      if (ex) return { spec: ex, explicit: null };
      if (tok.length === 1) return { pos: true };
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        const sp = exact(tok.slice(0, eq));
        if (sp) return { spec: sp, explicit: tok.slice(eq + 1) };
      }
      let matches;
      if (tok[1] === '-') {
        const prefix = eq === -1 ? tok : tok.slice(0, eq);
        matches = table.filter(([k]) => k.startsWith(prefix)).map(([k, sp]) => ({ spec: sp, opt: k, explicit: eq === -1 ? null : tok.slice(eq + 1) }));
      } else {
        const short = tok.slice(0, 2);
        matches = table.filter(([k]) => k === short || k.startsWith(tok)).map(([k, sp]) => ({ spec: sp, opt: k, explicit: k === short ? tok.slice(2) : null, cluster: k === short }));
      }
      if (matches.length > 1) this.fail(`ambiguous option: ${tok} could match ${matches.map((m) => m.opt).join(', ')}`);
      if (matches.length === 1) return matches[0];
      if (/^-\d+$|^-\d*\.\d+$/.test(tok) || tok.includes(' ')) return { pos: true };
      return { unknown: true };
    };
    const cls = [];
    for (let i = 0; i < argv.length; i++) {
      if (argv[i] === '--') {
        cls.push({ dd: true });
        break;
      }
      cls.push(classify(argv[i]));
    }
    // pass 2 (consume left to right; unknown options and words nobody consumed become "unrecognized arguments")
    const ns = {};
    for (const sp of specs) if (sp.dest) ns[sp.dest] = sp.default;
    const extras = [];
    const ignored = (sp, v) => this.fail(`argument ${label(sp)}: ignored explicit argument ${pyReprStr(v)}`);
    for (let i = 0; i < cls.length; i++) {
      const c = cls[i];
      if (c.dd) {
        extras.push(...argv.slice(i));
        break;
      }
      if (c.pos || c.unknown) {
        extras.push(argv[i]);
        continue;
      }
      const { spec: sp, explicit } = c;
      if (sp.kind === 'help') {
        if (explicit !== null && !(c.cluster && explicit[0] === 'h')) ignored(sp, explicit);
        return { help: true };
      } else if (sp.kind === 'flag') {
        if (explicit !== null) ignored(sp, explicit);
        ns[sp.dest] = true;
      } else if (explicit !== null) {
        ns[sp.dest] = explicit;
      } else {
        if (!cls[i + 1] || !cls[i + 1].pos) this.fail(`argument ${label(sp)}: expected one argument`);
        ns[sp.dest] = argv[++i];
      }
    }
    if (extras.length) this.fail(`unrecognized arguments: ${extras.join(' ')}`);
    return ns;
  }
}

const print = (s) => process.stdout.write(s + '\n');
const eprint = (s) => process.stderr.write(s + '\n');

export function main(argv) {
  const ap = new BootstrapParser({ prog: 'bootstrap.js', description: HELP_HEAD });
  ap.addArgument('--repo', { default: '.' });
  ap.addArgument('--answers');
  ap.addArgument('--dry-run', { action: 'store_true' });
  ap.addArgument('--detect-only', { action: 'store_true' });
  ap.addArgument('--upgrade', { action: 'store_true' });
  ap.addArgument('--all', { action: 'store_true', help: 'with --upgrade: every project in ~/.claude/kit-projects.json' });
  ap.addArgument('--protect', { action: 'store_true', help: 'set GitHub branch protection via gh' });
  ap.addArgument('--json', { action: 'store_true' });
  const a = ap.parseArgs(argv);
  if (a.help) {
    process.stdout.write(`${PY_USAGE}\n\n${HELP_HEAD}\n\n${HELP_OPTIONS}`);
    return 0;
  }
  if (a.all) {
    if (!a.upgrade) {
      eprint('--all is only valid with --upgrade');
      return 1;
    }
    const reg = path.join(regHome(), 'kit-projects.json');
    const projects = pyIter(K.isFile(reg) ? pyJsonLoads(readText(reg)) : []).map((p) => pyPathStr(p));
    if (!projects.length) {
      eprint('no registered projects (bootstrap registers them)');
      return 1;
    }
    const results = {};
    for (const proj of projects) {
      if (!fs.existsSync(path.join(proj, '.git'))) {
        results[proj] = { skipped: 'not a git repo' };
        continue;
      }
      results[proj] = upgradeProject(proj, {}, a.dry_run);
    }
    print(a.json
      ? K.jsonDumps(results, { indent: 2 })
      : Object.entries(results).map(([k, v]) => (has(v, 'written')
        ? `${k}: ${v.written.length} written, ${v.backed_up.length} backed up${v.checks?.restored ? `, RESTORED (${v.checks.regressed.join(', ')} regressed)` : ''}`
        : `${k}: ${pyRepr(v)}`)).join('\n'));
    return Object.values(results).some((v) => v.checks?.restored) ? 1 : 0;
  }
  const root = K.realResolve(a.repo);
  if (!fs.existsSync(path.join(root, '.git'))) {
    eprint(`bootstrap: ${root} is not a git repository`);
    return 1;
  }
  const answers = a.answers ? readJson(a.answers) : {};
  if (a.detect_only) {
    const det = detect(root);
    const out = { detection: det, questions: questions(det, answers) };
    print(a.json
      ? K.jsonDumps(out, { indent: 2 })
      : `stacks: ${pyRepr(det.stacks)}\nframeworks: ${pyRepr(det.frameworks)}\ncommands: ${K.jsonDumps(det.commands, { indent: 2 })}\nmissing tools: ${pyRepr(det.missing_tools)}\nquestions: ${out.questions.length}`);
    return 0;
  }
  const b = a.upgrade ? null : new Bootstrap(root, answers, a.dry_run, false);
  const result = a.upgrade ? upgradeProject(root, answers, a.dry_run) : b.run();
  const det = a.upgrade ? detect(root) : b.det;
  if (a.protect && !a.dry_run) {
    // Required checks are the workflow's job names, the names GitHub reports, read from the file just written.
    // They used to include step names (scope-diff, review-report, ...), which never report as checks, so every PR
    // would have waited forever (#68). The same list is what lane.js merge waits for.
    const checks = G.projectChecks(root);
    result.branch_protection = checks
      ? protectBranch(root, get(det, 'default_branch', 'main'), checks.required)
      : { ok: false, reason: `no ${G.WORKFLOW}; nothing to require` };
  }
  if (a.json) {
    print(K.jsonDumps(result, { indent: 2 }));
  } else {
    print(`agent-kit ${KIT_VERSION} ${a.upgrade ? 'upgrade' : 'bootstrap'}${a.dry_run ? ' (dry run)' : ''}: ${root}`);
    print(`stacks: ${det.stacks.join(', ') || 'unknown'}  frameworks: ${det.frameworks.join(', ') || '-'}  ci: ${det.ci || 'none'}`);
    for (const w of result.written) print(`  wrote   ${w}`);
    for (const s of result.skipped) print(`  kept    ${s}`);
    for (const s of result.backed_up) print(`  backup  ${s}`);
    const ch = get(result, 'checks', null);
    if (ch) {
      const was = (name) => (ch.before.find((c) => c.name === name)?.ok ? 'ok' : 'fail');
      for (const c of ch.after) print(`  check   ${c.name}: ${was(c.name)} -> ${c.ok ? 'ok' : 'fail'}`);
      if (ch.restored) {
        for (const c of ch.after.filter((x) => ch.regressed.includes(x.name))) eprint(`${c.name} regressed: ${c.output.split('\n')[0]}`);
        eprint(`RESTORED ${ch.restored.length} file(s) from ${ch.backup}/; the upgrade was not applied`);
      }
    }
    if (result.questions.length) {
      print('\nQuestions for the human (bootstrap does not guess these):');
      for (const q of result.questions) print(`  [${q.id}] ${q.question}`);
    }
    if (Object.keys(det.missing_tools).length) {
      print('\nTools not found (proposed, not installed):');
      for (const [k, v] of Object.entries(det.missing_tools)) print(`  ${k}: ${v}`);
    }
  }
  return get(result, 'checks', null)?.restored ? 1 : 0;
}

if (K.isMain(import.meta.url)) process.exitCode = main(process.argv.slice(2));
